const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');
const { Given, When, Then } = require('@cucumber/cucumber');

const ROOT = path.resolve(__dirname, '..', '..');
const INDEX = path.join(ROOT, 'index.html');
const APP = path.join(ROOT, 'js', 'app.js');
const STORAGE_KEY = 'todos-vanillajs';

// A reload is a fresh parse of the real index.html and a fresh execution of the real js/app.js
// in the SAME window, so localStorage and location.hash survive exactly as a browser reload
// leaves them. A second happy-dom Window would carry its own empty storage and prove nothing.
function reload(world) {
  const html = fs.readFileSync(INDEX, 'utf8');
  const inner = html.replace(/^[\s\S]*?<html[^>]*>/i, '').replace(/<\/html>[\s\S]*$/i, '');
  world.document.documentElement.innerHTML = inner;
  world.window.eval(fs.readFileSync(APP, 'utf8'));
  world.document.dispatchEvent(new world.window.Event('DOMContentLoaded', { bubbles: true }));
  world.window.dispatchEvent(new world.window.Event('load'));
}

function items(world) {
  return [...world.document.querySelectorAll('.todo-list li')];
}

function visibleItems(world) {
  return items(world).filter((li) => !isHidden(world, li));
}

function titleOf(li) {
  const label = li.querySelector('label');
  return label ? label.textContent.trim() : '';
}

function itemByTitle(world, title) {
  const li = visibleItems(world).find((el) => titleOf(el) === title);
  assert.ok(li, `no todo titled "${title}" in the list: ${JSON.stringify(visibleItems(world).map(titleOf))}`);
  return li;
}

function isHidden(world, el) {
  assert.ok(el, 'element is absent from the page');
  if (el.hasAttribute('hidden')) return true;
  const inline = el.getAttribute('style') || '';
  if (/display\s*:\s*none/i.test(inline)) return true;
  const computed = world.window.getComputedStyle(el);
  return computed && computed.display === 'none';
}

function section(world, name) {
  const el = world.document.querySelector(`.todoapp .${name}`);
  assert.ok(el, `the page has no "${name}" section`);
  return el;
}

function fire(world, el, type, init) {
  el.dispatchEvent(new world.window.Event(type, { bubbles: true, ...init }));
}

function key(world, el, name, code) {
  const EventCtor = world.window.KeyboardEvent;
  el.dispatchEvent(new EventCtor('keydown', { bubbles: true, key: name, keyCode: code, which: code }));
  el.dispatchEvent(new EventCtor('keyup', { bubbles: true, key: name, keyCode: code, which: code }));
}

function newTodoInput(world) {
  const input = world.document.querySelector('.new-todo');
  assert.ok(input, 'the page has no .new-todo input');
  return input;
}

function submitNewTodo(world, text) {
  const input = newTodoInput(world);
  input.value = text;
  fire(world, input, 'input');
  key(world, input, 'Enter', 13);
}

function editInput(world) {
  const li = items(world).find((el) => el.classList.contains('editing'));
  assert.ok(li, 'no todo is in editing mode');
  const input = li.querySelector('.edit');
  assert.ok(input, 'the editing todo has no .edit input');
  return input;
}

function stored(world) {
  const raw = world.localStorage.getItem(STORAGE_KEY);
  if (raw === null) return [];
  return JSON.parse(raw);
}

Given('the todo app is loaded', function () {
  assert.ok(this.document.querySelector('.todoapp'), 'the page has no .todoapp section');
});

Given('no todos are stored', function () {
  this.localStorage.removeItem(STORAGE_KEY);
});

Given('I have added the todo {string}', function (title) {
  submitNewTodo(this, title);
  itemByTitle(this, title);
});

Given('I have completed the todo {string}', function (title) {
  const toggle = itemByTitle(this, title).querySelector('.toggle');
  toggle.click();
  assert.ok(itemByTitle(this, title).classList.contains('completed'), `"${title}" did not complete`);
});

Given('I am editing the todo {string}', function (title) {
  fire(this, itemByTitle(this, title).querySelector('label'), 'dblclick');
  assert.ok(itemByTitle(this, title).classList.contains('editing'), `"${title}" did not enter editing mode`);
});

Given('I navigated to {string}', function (hash) {
  this.navigate(hash);
});

When('the todo app is reloaded', function () {
  reload(this);
});

When('I type {string} into the new todo input and press Enter', function (text) {
  submitNewTodo(this, text);
});

When('I click the toggle of the todo {string}', function (title) {
  itemByTitle(this, title).querySelector('.toggle').click();
});

When('I click the destroy button of the todo {string}', function (title) {
  itemByTitle(this, title).querySelector('.destroy').click();
});

When('I double-click the label of the todo {string}', function (title) {
  fire(this, itemByTitle(this, title).querySelector('label'), 'dblclick');
});

When('I type {string} into the edit input and press Enter', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  key(this, input, 'Enter', 13);
});

When('I type {string} into the edit input and press Escape', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  key(this, input, 'Escape', 27);
});

When('I type {string} into the edit input and blur it', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  fire(this, input, 'blur');
});

When('I click the mark all as complete checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(toggleAll, 'the page has no .toggle-all checkbox');
  toggleAll.click();
});

When('I click the clear completed button', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page has no .clear-completed button');
  button.click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I click the filter link {string}', function (name) {
  const link = [...this.document.querySelectorAll('.filters a')].find((a) => a.textContent.trim() === name);
  assert.ok(link, `the page has no "${name}" filter link`);
  link.click();
});

Then('the todo list shows {string}', function (title) {
  assert.deepStrictEqual(
    visibleItems(this).map(titleOf).includes(title),
    true,
    `list holds ${JSON.stringify(visibleItems(this).map(titleOf))}`,
  );
});

Then('the todo list has {int} items', function (count) {
  assert.strictEqual(visibleItems(this).length, count, `list holds ${JSON.stringify(visibleItems(this).map(titleOf))}`);
});

Then('the new todo input is empty', function () {
  assert.strictEqual(newTodoInput(this).value, '');
});

Then('the {string} section is hidden', function (name) {
  assert.strictEqual(isHidden(this, section(this, name)), true, `the "${name}" section is visible`);
});

Then('the {string} section is visible', function (name) {
  assert.strictEqual(isHidden(this, section(this, name)), false, `the "${name}" section is hidden`);
});

Then('the todo {string} is marked completed', function (title) {
  const li = itemByTitle(this, title);
  assert.ok(li.classList.contains('completed'), `"${title}" has no completed class`);
  assert.strictEqual(li.querySelector('.toggle').checked, true, `"${title}" toggle is unchecked`);
});

Then('the todo {string} is marked active', function (title) {
  const li = itemByTitle(this, title);
  assert.strictEqual(li.classList.contains('completed'), false, `"${title}" still has the completed class`);
  assert.strictEqual(li.querySelector('.toggle').checked, false, `"${title}" toggle is checked`);
});

Then('the todo {string} is in editing mode', function (title) {
  assert.ok(itemByTitle(this, title).classList.contains('editing'), `"${title}" has no editing class`);
});

Then('no todo is in editing mode', function () {
