(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	var todos = [];
	var filter = 'all';
	var editingId = null;

	/**
	 * @planks("localStorage key {string} holds {int} stored todos")
	 * @planks("stored todo {int} has title {string} and completed {word}")
	 * @planks("stored todo {int} has an id")
	 */
	function save() {
		window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	/**
	 * @planks("the todo app is reloaded")
	 * @planks("no todos are stored")
	 */
	function load() {
		var raw = window.localStorage.getItem(STORAGE_KEY);
		todos = raw === null ? [] : JSON.parse(raw);
	}

	/**
	 * @planks("I type {string} into the new todo input and press Enter")
	 * @planks("I have added the todo {string}")
	 */
	function createTodo(title) {
		var trimmed = title.trim();
		if (trimmed === '') {
			return;
		}
		todos.push({
			id: String(Date.now()) + '-' + String(todos.length) + '-' + String(Math.random()).slice(2),
			title: trimmed,
			completed: false
		});
		save();
		render();
	}

	/**
	 * @planks("I click the toggle of the todo {string}")
	 * @planks("I have completed the todo {string}")
	 */
	function toggleTodo(id) {
		var todo = find(id);
		todo.completed = !todo.completed;
		save();
		render();
	}

	/**
	 * @planks("I click the destroy button of the todo {string}")
	 */
	function destroyTodo(id) {
		todos = todos.filter(function (todo) {
			return todo.id !== id;
		});
		save();
		render();
	}

	/**
	 * @planks("I click the mark all as complete checkbox")
	 */
	function toggleAll() {
		var completing = todos.some(function (todo) {
			return !todo.completed;
		});
		todos.forEach(function (todo) {
			todo.completed = completing;
		});
		save();
		render();
	}

	/**
	 * @planks("I click the clear completed button")
	 */
	function clearCompleted() {
		todos = todos.filter(function (todo) {
			return !todo.completed;
		});
		save();
		render();
	}

	/**
	 * @planks("I double-click the label of the todo {string}")
	 * @planks("I am editing the todo {string}")
	 * @planks("the edit input of the todo {string} holds {string}")
	 * @planks("the edit input of the todo {string} has focus")
	 * @planks("the todo {string} is in editing mode")
	 */
	function startEditing(id) {
		editingId = id;
		render();
		var input = document.querySelector('.todo-list li.editing .edit');
		input.focus();
	}

	/**
	 * @planks("I type {string} into the edit input and press Enter")
	 * @planks("I type {string} into the edit input and blur it")
	 */
	function saveEdit(id, value) {
		var trimmed = value.trim();
		editingId = null;
		if (trimmed === '') {
			destroyTodo(id);
			return;
		}
		find(id).title = trimmed;
		save();
		render();
	}

	/**
	 * @planks("I type {string} into the edit input and press Escape")
	 * @planks("no todo is in editing mode")
	 */
	function cancelEdit() {
		editingId = null;
		render();
	}

	function find(id) {
		return todos.filter(function (todo) {
			return todo.id === id;
		})[0];
	}

	function visibleTodos() {
		return todos.filter(function (todo) {
			if (filter === 'active') {
				return !todo.completed;
			}
			if (filter === 'completed') {
				return todo.completed;
			}
			return true;
		});
	}

	/**
	 * @planks("I navigate to {string}")
	 * @planks("I navigated to {string}")
	 * @planks("I click the filter link {string}")
	 * @planks("the filter link {string} is selected")
	 * @planks("the filter link {string} is not selected")
	 */
	function readRoute() {
		var hash = window.location.hash;
		if (hash === '#/active' || hash === '#!/active') {
			filter = 'active';
			return;
		}
		if (hash === '#/completed' || hash === '#!/completed') {
			filter = 'completed';
			return;
		}
		filter = 'all';
	}

	/**
	 * @planks("the todo list shows {string}")
	 * @planks("the todo list has {int} items")
	 * @planks("the {string} section is hidden")
	 * @planks("the {string} section is visible")
	 * @planks("the todo {string} is marked completed")
	 * @planks("the todo {string} is marked active")
	 * @planks("the counter reads {string}")
	 * @planks("the counter strong element reads {string}")
	 * @planks("the mark all as complete checkbox is checked")
	 * @planks("the mark all as complete checkbox is unchecked")
	 * @planks("the clear completed button is hidden")
	 * @planks("the clear completed button is visible")
	 */
	function render() {
		var main = document.querySelector('.main');
		var footer = document.querySelector('.footer');
		var list = document.querySelector('.todo-list');
		var active = todos.filter(function (todo) {
			return !todo.completed;
		}).length;
		var completed = todos.length - active;

		main.style.display = todos.length === 0 ? 'none' : '';
		footer.style.display = todos.length === 0 ? 'none' : '';

		list.innerHTML = '';
		visibleTodos().forEach(function (todo) {
			list.appendChild(itemElement(todo));
		});

		document.querySelector('.todo-count').innerHTML =
			'<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';
		document.querySelector('.toggle-all').checked = todos.length > 0 && active === 0;
		document.querySelector('.clear-completed').style.display = completed === 0 ? 'none' : '';

		var links = document.querySelectorAll('.filters a');
		Array.prototype.forEach.call(links, function (link) {
			var href = link.getAttribute('href');
			var linkFilter = href === '#/active' ? 'active' : href === '#/completed' ? 'completed' : 'all';
			link.className = linkFilter === filter ? 'selected' : '';
		});
	}

	/**
	 * @planks("the todo list shows {string}")
	 * @planks("the todo {string} is marked completed")
	 * @planks("the todo {string} is in editing mode")
	 */
	function itemElement(todo) {
		var li = document.createElement('li');
		var classes = [];
		if (todo.completed) {
			classes.push('completed');
		}
		if (todo.id === editingId) {
			classes.push('editing');
		}
		li.className = classes.join(' ');

		var view = document.createElement('div');
		view.className = 'view';

		var toggle = document.createElement('input');
		toggle.className = 'toggle';
		toggle.type = 'checkbox';
		toggle.checked = todo.completed;
		toggle.addEventListener('change', function () {
			toggleTodo(todo.id);
		});

		var label = document.createElement('label');
		label.textContent = todo.title;
		label.addEventListener('dblclick', function () {
			startEditing(todo.id);
		});

		var destroy = document.createElement('button');
		destroy.className = 'destroy';
		destroy.addEventListener('click', function () {
			destroyTodo(todo.id);
		});

		view.appendChild(toggle);
		view.appendChild(label);
		view.appendChild(destroy);

		var edit = document.createElement('input');
		edit.className = 'edit';
		edit.value = todo.title;
		edit.addEventListener('keydown', function (event) {
			var code = event.keyCode || event.which;
			if (code === ENTER_KEY || event.key === 'Enter') {
				saveEdit(todo.id, edit.value);
			}
			if (code === ESCAPE_KEY || event.key === 'Escape') {
				edit.value = todo.title;
				cancelEdit();
			}
		});
		edit.addEventListener('blur', function () {
			if (editingId === todo.id) {
				saveEdit(todo.id, edit.value);
			}
		});

		li.appendChild(view);
		li.appendChild(edit);
		return li;
	}

	/**
	 * @planks("the todo app is loaded")
	 * @planks("the new todo input is empty")
	 */
	function init() {
		var newTodo = document.querySelector('.new-todo');
		newTodo.addEventListener('keydown', function (event) {
			var code = event.keyCode || event.which;
			if (code === ENTER_KEY || event.key === 'Enter') {
				createTodo(newTodo.value);
				newTodo.value = '';
			}
		});
		document.querySelector('.toggle-all').addEventListener('change', toggleAll);
		document.querySelector('.clear-completed').addEventListener('click', clearCompleted);
		window.onhashchange = function () {
			readRoute();
			render();
		};
		load();
		readRoute();
		render();
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})();

